style.css:
@-moz-document domain("google.com") {
/* ===== WHOLE PAGE ===== */
    html,
    body {
        background: linear-gradient(
            135deg,
            #fff0f7,
            #f3edff,
            #eaf7ff
        ) !important;
        color: #6d6175 !important;
    }

    /* ===== GOOGLE LOGO AREA ===== */
    .k1zIA {
        margin-top: 20px !important;
    }

    /* ===== SEARCH BOX ===== */
    .RNNXgb {
        background: #ffffffdd !important;
        border: 3px solid #f6c9df !important;
        border-radius: 30px !important;
        box-shadow: 0 5px 20px rgba(214, 170, 200, 0.25) !important;
        transition: 0.3s ease !important;
    }

    .RNNXgb:hover,
    .RNNXgb:focus-within {
        border-color: #d9c5f2 !important;
        box-shadow: 0 7px 25px rgba(190, 160, 220, 0.3) !important;
        transform: translateY(-2px) !important;
    }

    /* Search text */
    .gLFyf {
        color: #75677c !important;
        font-family: "Trebuchet MS", sans-serif !important;
    }

    /* ===== SEARCH BUTTONS ===== */
    .FPdoLc input[type="submit"] {
        background: #ffe0ee !important;
        color: #765f70 !important;
        border: 2px solid #f5c6dc !important;
        border-radius: 20px !important;
        font-family: "Trebuchet MS", sans-serif !important;
        transition: 0.2s ease !important;
    }

    .FPdoLc input[type="submit"]:hover {
        background: #eadcff !important;
        border-color: #d3b9ee !important;
        transform: translateY(-2px) !important;
    }

    /* ===== TOP RIGHT LINKS ===== */
    a {
        color: #8b7895 !important;
        font-family: "Trebuchet MS", sans-serif !important;
    }

    a:hover {
        color: #d58eb5 !important;
    }

    /* ===== SEARCH RESULTS ===== */

    .MjjYud {
        background: rgba(255, 255, 255, 0.55) !important;
        border-radius: 18px !important;
        padding: 12px !important;
        margin: 10px 0 !important;
        box-shadow: 0 4px 15px rgba(210, 180, 205, 0.15) !important;
    }

    /* Result titles */
    h3 {
        color: #a76f9c !important;
        font-family: "Trebuchet MS", sans-serif !important;
    }

    h3:hover {
        color: #d48bb5 !important;
    }

    /* Result descriptions */
    .VwiC3b {
        color: #776d7b !important;
    }

    /* ===== SEARCH TABS ===== */

    .hdtb-mitem {
        color: #927f9c !important;
        font-family: "Trebuchet MS", sans-serif !important;
    }

    .hdtb-mitem:hover {
        color: #d68eb8 !important;
    }

    /* ===== GOOGLE CARDS ===== */

    .MjjYud,
    .g {
        border-radius: 18px !important;
    }

    /* ===== SCROLLBAR ===== */

    ::-webkit-scrollbar {
        width: 12px !important;
    }

    ::-webkit-scrollbar-track {
        background: #fff1f7 !important;
    }

    ::-webkit-scrollbar-thumb {
        background: linear-gradient(
            #f7c8df,
            #d9c9f3
        ) !important;
        border-radius: 20px !important;
        border: 3px solid #fff1f7 !important;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #d7b4df !important;
    }

    /* ===== GOOGLE FOOTER ===== */

    .fbar {
        background: rgba(255, 230, 242, 0.8) !important;
        border-top: 2px solid #f4d2e2 !important;
    }

    /* ===== SOFT SELECTION ===== */

    ::selection {
        background: #f4c9df !important;
        color: #684f64 !important;
    }
}
